export const getExportTenderDraftUrl = (
  id: number,
  params: ExportTenderDraftParams,
) => {
  const normalizedParams = new URLSearchParams();

  Object.entries(params || {}).forEach(([key, value]) => {
    if (value !== undefined) {
      normalizedParams.append(key, value === null ? "null" : value.toString());
    }
  });

  const stringifiedParams = normalizedParams.toString();

  return stringifiedParams.length > 0
    ? `/api/tenders/${id}/draft/export?${stringifiedParams}`
    : `/api/tenders/${id}/draft/export`;
};

export const exportTenderDraft = async (
  id: number,
  params: ExportTenderDraftParams,
  options?: RequestInit,
): Promise<Blob> => {
  return customFetch<Blob>(getExportTenderDraftUrl(id, params), {
    ...options,
    method: "GET",
  });
};

